import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  Grid,
  List,
  ListItem,
  ListItemText,
  ListItemSecondaryAction,
  IconButton,
  Divider,
  Chip,
  useTheme,
  useMediaQuery,
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import { Recipe } from '../types/Recipe';

interface MealTrackerProps {
  meals: Recipe[];
  onRemoveMeal: (mealId: string) => void;
}

type NutritionCard = {
  label: string;
  value: number;
  unit: string;
  color: 'primary' | 'secondary' | 'info' | 'warning';
};

const MealTracker: React.FC<MealTrackerProps> = ({ meals, onRemoveMeal }) => {
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const getMealCategory = (mealId: string): string => {
    const id = parseInt(mealId);
    if (id >= 100 && id < 200) return 'Ontbijt';
    if (id >= 200 && id < 300) return 'Lunch';
    if (id >= 300 && id < 400) return 'Snack';
    return 'Avondmaaltijd';
  };

  const calculateNutrition = (meal: Recipe) => {
    // Dit is een voorbeeld - in een echte app zou je echte voedingswaarden gebruiken
    return {
      calories: Math.round(meal.ingredients.length * 100 * meal.servings),
      protein: Math.round(meal.ingredients.length * 20 * meal.servings),
      carbs: Math.round(meal.ingredients.length * 30 * meal.servings),
      fat: Math.round(meal.ingredients.length * 10 * meal.servings),
    };
  };

  const totalNutrition = meals.reduce((acc, meal) => {
    const nutrition = calculateNutrition(meal);
    return {
      calories: acc.calories + nutrition.calories,
      protein: acc.protein + nutrition.protein,
      carbs: acc.carbs + nutrition.carbs,
      fat: acc.fat + nutrition.fat,
    };
  }, { calories: 0, protein: 0, carbs: 0, fat: 0 });

  const mealsByCategory = meals.reduce((acc, meal) => {
    const category = getMealCategory(meal.id);
    if (!acc[category]) {
      acc[category] = [];
    }
    acc[category].push(meal);
    return acc;
  }, {} as Record<string, Recipe[]>);

  const nutritionCards: NutritionCard[] = [
    { label: 'Calorieën', value: totalNutrition.calories, unit: 'kcal', color: 'primary' },
    { label: 'Eiwitten', value: totalNutrition.protein, unit: 'g', color: 'secondary' },
    { label: 'Koolhydraten', value: totalNutrition.carbs, unit: 'g', color: 'info' },
    { label: 'Vetten', value: totalNutrition.fat, unit: 'g', color: 'warning' },
  ];

  return (
    <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      <Typography 
        variant="h5" 
        component="h2" 
        sx={{ 
          fontWeight: 600,
          mb: 3,
        }}
      >
        Meal Tracker - {selectedDate.toLocaleDateString('nl-NL')}
      </Typography>

      <Grid container spacing={2} sx={{ mb: 3 }}>
        {nutritionCards.map((card) => (
          <Grid item xs={6} sm={3} key={card.label}>
            <Paper 
              sx={{ 
                p: 2, 
                textAlign: 'center',
                height: '100%',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'center',
                transition: 'transform 0.2s, box-shadow 0.2s',
                '&:hover': {
                  transform: 'translateY(-4px)',
                  boxShadow: theme.shadows[4],
                },
              }}
            >
              <Typography 
                variant="h4" 
                component="div" 
                sx={{ 
                  fontWeight: 700,
                  color: theme.palette[card.color].main,
                  mb: 1,
                }}
              >
                {card.value}
              </Typography>
              <Typography 
                variant="body2" 
                color="text.secondary"
                sx={{ fontWeight: 500 }}
              >
                {card.label}
              </Typography>
              <Typography 
                variant="caption" 
                color="text.secondary"
                sx={{ mt: 0.5 }}
              >
                {card.unit}
              </Typography>
            </Paper>
          </Grid>
        ))}
      </Grid>

      <Box sx={{ 
        flexGrow: 1, 
        overflow: 'auto',
        '&::-webkit-scrollbar': {
          width: '8px',
        },
        '&::-webkit-scrollbar-track': {
          background: '#f1f1f1',
          borderRadius: '4px',
        },
        '&::-webkit-scrollbar-thumb': {
          background: theme.palette.primary.main,
          borderRadius: '4px',
          '&:hover': {
            background: theme.palette.primary.dark,
          },
        },
      }}>
        {Object.entries(mealsByCategory).map(([category, categoryMeals]) => (
          <Box key={category} sx={{ mb: 3 }}>
            <Typography 
              variant="h6" 
              sx={{ 
                mb: 2,
                color: theme.palette.primary.main,
                fontWeight: 600,
                display: 'flex',
                alignItems: 'center',
                gap: 1,
              }}
            >
              {category}
              <Chip 
                label={categoryMeals.length} 
                size="small" 
                color="primary" 
                variant="outlined"
                sx={{ ml: 1 }}
              />
            </Typography>
            <Paper 
              elevation={0} 
              sx={{ 
                bgcolor: 'background.paper',
                borderRadius: 2,
                border: `1px solid ${theme.palette.divider}`,
              }}
            >
              <List>
                {categoryMeals.map((meal, index) => {
                  const nutrition = calculateNutrition(meal);
                  return (
                    <React.Fragment key={meal.id}>
                      <ListItem 
                        sx={{ 
                          py: 1.5,
                          '&:hover': {
                            bgcolor: 'action.hover',
                          },
                        }}
                      >
                        <ListItemText
                          primary={
                            <Typography 
                              sx={{ 
                                fontWeight: 500,
                                display: 'flex',
                                alignItems: 'center',
                                gap: 1,
                              }}
                            >
                              {meal.name}
                              <Chip
                                label={`${nutrition.calories} kcal`}
                                size="small"
                                color="primary"
                                variant="outlined"
                                sx={{ ml: 1 }}
                              />
                            </Typography>
                          }
                          secondary={
                            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mt: 1 }}>
                              <Chip
                                label={`${nutrition.protein}g eiwit`}
                                size="small"
                                color="secondary"
                                variant="outlined"
                              />
                              <Chip
                                label={`${nutrition.carbs}g koolhydraten`}
                                size="small"
                                color="info"
                                variant="outlined"
                              />
                              <Chip
                                label={`${nutrition.fat}g vet`}
                                size="small"
                                color="warning"
                                variant="outlined"
                              />
                            </Box>
                          }
                        />
                        <ListItemSecondaryAction>
                          <IconButton
                            edge="end"
                            aria-label="delete"
                            onClick={() => onRemoveMeal(meal.id)}
                            sx={{
                              color: theme.palette.error.main,
                              '&:hover': {
                                bgcolor: theme.palette.error.light + '20',
                              },
                            }}
                          >
                            <DeleteIcon />
                          </IconButton>
                        </ListItemSecondaryAction>
                      </ListItem>
                      {index < categoryMeals.length - 1 && <Divider />}
                    </React.Fragment>
                  );
                })}
              </List>
            </Paper>
          </Box>
        ))}
      </Box>
    </Box>
  );
};

export default MealTracker; 