import React from 'react';
import {
  Box,
  Typography,
  List,
  ListItem,
  ListItemText,
  ListItemSecondaryAction,
  IconButton,
  Divider,
  Paper,
  Chip,
  useTheme,
  useMediaQuery,
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import ShoppingCartIcon from '@mui/icons-material/ShoppingCart';

interface ShoppingListProps {
  ingredients: { name: string; amount: number; unit: string }[];
  onRemoveIngredient: (index: number) => void;
}

const categories = {
  vegetables: ['broccoli', 'wortel', 'ui', 'knoflook', 'tomaat', 'komkommer', 'paprika', 'spinazie', 'sla', 'aardappel', 'zoete aardappel', 'courgette', 'aubergine', 'prei', 'kool', 'sperziebonen', 'doperwten', 'maïs', 'champignons'],
  meat: ['kip', 'varkensvlees', 'rundvlees', 'kalkoen', 'vis', 'zalm', 'tonijn', 'hamburger', 'worst', 'spek', 'ham'],
  dairy: ['melk', 'kaas', 'yoghurt', 'kwark', 'boter', 'room', 'ei', 'eieren'],
  bread: ['brood', 'tortilla', 'wrap', 'cracker', 'toast'],
  canned: ['tomatensaus', 'bonen', 'maïs', 'tuna', 'tonijn', 'soep'],
  frozen: ['groenten', 'fruit', 'vis', 'kip'],
  other: ['rijst', 'pasta', 'couscous', 'quinoa', 'olijfolie', 'azijn', 'kruiden', 'specerijen', 'noten', 'zaden', 'muesli', 'havermout', 'soja', 'tofu', 'tempeh'],
};

const ShoppingList: React.FC<ShoppingListProps> = ({ ingredients, onRemoveIngredient }) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const groupedIngredients = ingredients.reduce((acc, ingredient) => {
    const category = Object.entries(categories).find(([_, items]) =>
      items.some(item => ingredient.name.toLowerCase().includes(item))
    )?.[0] || 'other';

    if (!acc[category]) {
      acc[category] = [];
    }
    acc[category].push(ingredient);
    return acc;
  }, {} as Record<string, typeof ingredients>);

  const categoryLabels: Record<string, string> = {
    vegetables: 'Groenten',
    meat: 'Vlees & Vis',
    dairy: 'Zuivel & Eieren',
    bread: 'Brood & Wraps',
    canned: 'Blik & Pot',
    frozen: 'Diepvries',
    other: 'Overig',
  };

  return (
    <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      <Box sx={{ 
        display: 'flex', 
        alignItems: 'center', 
        mb: 3,
        gap: 1,
      }}>
        <ShoppingCartIcon color="primary" sx={{ fontSize: 28 }} />
        <Typography variant="h5" component="h2" sx={{ fontWeight: 600 }}>
          Boodschappenlijst
        </Typography>
      </Box>

      <Box sx={{ 
        flexGrow: 1, 
        overflow: 'auto',
        '&::-webkit-scrollbar': {
          width: '8px',
        },
        '&::-webkit-scrollbar-track': {
          background: '#f1f1f1',
          borderRadius: '4px',
        },
        '&::-webkit-scrollbar-thumb': {
          background: theme.palette.primary.main,
          borderRadius: '4px',
          '&:hover': {
            background: theme.palette.primary.dark,
          },
        },
      }}>
        {Object.entries(groupedIngredients).map(([category, items]) => (
          <Box key={category} sx={{ mb: 3 }}>
            <Typography 
              variant="h6" 
              sx={{ 
                mb: 1,
                color: theme.palette.primary.main,
                fontWeight: 600,
                display: 'flex',
                alignItems: 'center',
                gap: 1,
              }}
            >
              {categoryLabels[category]}
              <Chip 
                label={items.length} 
                size="small" 
                color="primary" 
                variant="outlined"
                sx={{ ml: 1 }}
              />
            </Typography>
            <Paper 
              elevation={0} 
              sx={{ 
                bgcolor: 'background.paper',
                borderRadius: 2,
                border: `1px solid ${theme.palette.divider}`,
              }}
            >
              <List>
                {items.map((item, index) => (
                  <React.Fragment key={index}>
                    <ListItem 
                      sx={{ 
                        py: 1.5,
                        '&:hover': {
                          bgcolor: 'action.hover',
                        },
                      }}
                    >
                      <ListItemText
                        primary={
                          <Typography 
                            sx={{ 
                              fontWeight: 500,
                              display: 'flex',
                              alignItems: 'center',
                              gap: 1,
                            }}
                          >
                            {item.name}
                            <Chip
                              label={`${item.amount} ${item.unit}`}
                              size="small"
                              color="primary"
                              variant="outlined"
                              sx={{ ml: 1 }}
                            />
                          </Typography>
                        }
                      />
                      <ListItemSecondaryAction>
                        <IconButton
                          edge="end"
                          aria-label="delete"
                          onClick={() => onRemoveIngredient(index)}
                          sx={{
                            color: theme.palette.error.main,
                            '&:hover': {
                              bgcolor: theme.palette.error.light + '20',
                            },
                          }}
                        >
                          <DeleteIcon />
                        </IconButton>
                      </ListItemSecondaryAction>
                    </ListItem>
                    {index < items.length - 1 && <Divider />}
                  </React.Fragment>
                ))}
              </List>
            </Paper>
          </Box>
        ))}
      </Box>
    </Box>
  );
};

export default ShoppingList; 