import React, { useState } from 'react';
import {
  Container,
  CssBaseline,
  ThemeProvider,
  createTheme,
  Box,
  Typography,
  Paper,
  AppBar,
  Toolbar,
  Fab,
  Chip,
  Button,
  Grid,
} from '@mui/material';
import ShareIcon from '@mui/icons-material/Share';
import MealPlanner from './components/MealPlanner';
import ShoppingList from './components/ShoppingList';
import Navigation from './components/Navigation';
import MealTracker from './components/MealTracker';
import { Recipe, MealPlan } from './types/Recipe';
import MealCard from './components/MealCard';
import AddIcon from '@mui/icons-material/Add';

const theme = createTheme({
  palette: {
    mode: 'light',
    primary: {
      main: '#1a237e',
      light: '#534bae',
      dark: '#000051',
    },
    secondary: {
      main: '#ff3d00',
      light: '#ff7539',
      dark: '#c30000',
    },
    background: {
      default: '#f5f5f5',
      paper: '#ffffff',
    },
  },
  typography: {
    fontFamily: '"Poppins", "Roboto", "Helvetica", "Arial", sans-serif',
    h1: {
      fontWeight: 700,
      fontSize: '2rem',
      '@media (min-width:600px)': {
        fontSize: '2.5rem',
      },
    },
    h2: {
      fontWeight: 600,
      fontSize: '1.5rem',
      '@media (min-width:600px)': {
        fontSize: '2rem',
      },
    },
    h5: {
      fontWeight: 600,
    },
    h6: {
      fontWeight: 600,
    },
  },
  components: {
    MuiPaper: {
      styleOverrides: {
        root: {
          borderRadius: 16,
          boxShadow: '0 4px 6px rgba(0,0,0,0.1)',
        },
      },
    },
    MuiCard: {
      styleOverrides: {
        root: {
          borderRadius: 16,
        },
      },
    },
    MuiButton: {
      styleOverrides: {
        root: {
          borderRadius: 8,
          textTransform: 'none',
          fontWeight: 600,
        },
      },
    },
    MuiFab: {
      styleOverrides: {
        root: {
          borderRadius: 12,
        },
      },
    },
  },
});

function App() {
  const [mealPlan, setMealPlan] = useState<MealPlan>({ meals: [] });
  const [selectedMeal, setSelectedMeal] = useState<Recipe | null>(null);
  const [shoppingList, setShoppingList] = useState<{ name: string; amount: number; unit: string }[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<string>('home');
  const [trackedMeals, setTrackedMeals] = useState<Recipe[]>([]);

  const handleAddMeal = (meal: Recipe, servings: number) => {
    const newMeal = { ...meal, servings };
    setMealPlan(prev => ({
      meals: [...prev.meals, newMeal]
    }));
  };

  const handleUpdateServings = (mealId: string, servings: number) => {
    setMealPlan(prev => ({
      meals: prev.meals.map(meal =>
        meal.id === mealId ? { ...meal, servings } : meal
      )
    }));
  };

  const handleUpdateRating = (mealId: string, rating: number) => {
    setMealPlan(prev => ({
      meals: prev.meals.map(meal =>
        meal.id === mealId ? { ...meal, rating } : meal
      )
    }));
  };

  const handleShoppingListUpdate = (ingredients: { name: string; amount: number; unit: string }[]) => {
    setShoppingList(ingredients);
  };

  const handleRemoveTrackedMeal = (mealId: string) => {
    setTrackedMeals(prev => prev.filter(meal => meal.id !== mealId));
  };

  const handleShareShoppingList = () => {
    const text = shoppingList
      .map(item => `${item.amount} ${item.unit} ${item.name}`)
      .join('\n');
    const whatsappUrl = `https://wa.me/?text=${encodeURIComponent(text)}`;
    window.open(whatsappUrl, '_blank');
  };

  const renderContent = () => {
    switch (selectedCategory) {
      case 'home':
        return (
          <Box sx={{ 
            display: 'flex', 
            flexDirection: 'column',
            gap: 3,
            height: '100%'
          }}>
            <Paper elevation={3} sx={{ p: 3 }}>
              <Box sx={{ 
                display: 'flex', 
                alignItems: 'center', 
                justifyContent: 'space-between',
                mb: 3,
              }}>
                <Typography variant="h5" component="h2" sx={{ fontWeight: 600 }}>
                  Geselecteerde maaltijden
                </Typography>
                <Button
                  variant="contained"
                  startIcon={<AddIcon />}
                  onClick={() => setSelectedCategory('all')}
                  sx={{
                    borderRadius: 2,
                    textTransform: 'none',
                    fontWeight: 600,
                    px: 3,
                    '&:hover': {
                      bgcolor: theme.palette.primary.dark,
                    },
                  }}
                >
                  Maaltijd toevoegen
                </Button>
              </Box>

              <Grid container spacing={3}>
                {mealPlan.meals.map((meal) => (
                  <Grid item xs={12} sm={6} md={4} key={meal.id}>
                    <MealCard
                      meal={meal}
                      onSelect={setSelectedMeal}
                      onUpdateServings={handleUpdateServings}
                      onUpdateRating={handleUpdateRating}
                    />
                  </Grid>
                ))}
              </Grid>
            </Paper>

            <Paper elevation={3} sx={{ p: 3, flexGrow: 1 }}>
              <Box sx={{ 
                display: 'flex', 
                alignItems: 'center', 
                justifyContent: 'space-between',
                mb: 3,
              }}>
                <Typography variant="h5" component="h2" sx={{ fontWeight: 600 }}>
                  Boodschappenlijst
                </Typography>
                {shoppingList.length > 0 && (
                  <Button
                    variant="contained"
                    startIcon={<ShareIcon />}
                    onClick={handleShareShoppingList}
                    sx={{
                      borderRadius: 2,
                      textTransform: 'none',
                      fontWeight: 600,
                      px: 3,
                      '&:hover': {
                        bgcolor: theme.palette.primary.dark,
                      },
                    }}
                  >
                    Deel via WhatsApp
                  </Button>
                )}
              </Box>
              <ShoppingList
                ingredients={shoppingList}
                onRemoveIngredient={(index) => {
                  // Implementation needed
                }}
              />
            </Paper>
          </Box>
        );
      case 'tracker':
        return (
          <Paper elevation={3} sx={{ p: 3, height: '100%' }}>
            <MealTracker
              meals={trackedMeals}
              onRemoveMeal={handleRemoveTrackedMeal}
            />
          </Paper>
        );
      case 'all':
      case 'breakfast':
      case 'lunch':
      case 'dinner':
      case 'snack':
      default:
        return (
          <Box sx={{ 
            display: 'grid', 
            gap: 3, 
            gridTemplateColumns: { 
              xs: '1fr',
              md: '1fr 1fr' 
            },
            height: '100%'
          }}>
            <Paper elevation={3} sx={{ p: 3, height: '100%' }}>
              <MealPlanner
                mealPlan={mealPlan}
                onAddMeal={handleAddMeal}
                onUpdateServings={handleUpdateServings}
                onUpdateRating={handleUpdateRating}
                selectedMeal={selectedMeal}
                onSelectMeal={setSelectedMeal}
                onShoppingListUpdate={handleShoppingListUpdate}
                selectedCategory={selectedCategory}
              />
            </Paper>
            
            <Box sx={{ position: 'relative', height: '100%' }}>
              <Paper elevation={3} sx={{ p: 3, height: '100%' }}>
                <ShoppingList
                  ingredients={shoppingList}
                  onRemoveIngredient={(index) => {
                    // Implementation needed
                  }}
                />
              </Paper>
              {shoppingList.length > 0 && (
                <Fab
                  color="primary"
                  aria-label="share"
                  onClick={handleShareShoppingList}
                  sx={{
                    position: 'fixed',
                    bottom: 16,
                    right: 16,
                    zIndex: 1000,
                  }}
                >
                  <ShareIcon />
                </Fab>
              )}
            </Box>
          </Box>
        );
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
        <AppBar 
          position="static" 
          color="primary" 
          elevation={0}
          sx={{
            background: 'linear-gradient(45deg, #1a237e 30%, #534bae 90%)',
          }}
        >
          <Toolbar>
            <Navigation onCategoryChange={setSelectedCategory} />
            <Box sx={{ flexGrow: 1, display: 'flex', alignItems: 'center', gap: 1 }}>
              <Typography 
                variant="h6" 
                component="div" 
                sx={{ 
                  fontWeight: 700,
                  letterSpacing: 1,
                }}
              >
                MAALTIJDPLANNER
              </Typography>
              <Chip
                label="v1.2.0"
                size="small"
                sx={{
                  bgcolor: 'rgba(255,255,255,0.1)',
                  color: 'white',
                  fontWeight: 500,
                  fontSize: '0.75rem',
                }}
              />
            </Box>
          </Toolbar>
        </AppBar>

        <Box sx={{ 
          flexGrow: 1, 
          bgcolor: 'background.default', 
          py: 3,
          px: { xs: 2, sm: 3 },
        }}>
          <Container maxWidth="lg" sx={{ height: '100%' }}>
            {renderContent()}
          </Container>
        </Box>
      </Box>
    </ThemeProvider>
  );
}

export default App; 