import React, { useState } from 'react';
import {
  Card,
  CardContent,
  CardActions,
  Typography,
  IconButton,
  TextField,
  Box,
  Chip,
  useTheme,
  useMediaQuery,
} from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import MuscleRating from './MuscleRating';
import { Recipe } from '../types/Recipe';

interface MealCardProps {
  meal: Recipe;
  onSelect: (meal: Recipe) => void;
  onUpdateServings: (mealId: string, servings: number) => void;
  onUpdateRating: (mealId: string, rating: number) => void;
}

const MealCard: React.FC<MealCardProps> = ({
  meal,
  onSelect,
  onUpdateServings,
  onUpdateRating,
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [servings, setServings] = useState(meal.servings);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const handleServingsChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseInt(event.target.value);
    if (value > 0) {
      setServings(value);
      onUpdateServings(meal.id, value);
    }
  };

  const handleKeyPress = (event: React.KeyboardEvent) => {
    if (event.key === 'Enter') {
      setIsEditing(false);
    }
  };

  return (
    <Card 
      sx={{ 
        height: '100%',
        display: 'flex',
        flexDirection: 'column',
        transition: 'transform 0.2s, box-shadow 0.2s',
        '&:hover': {
          transform: 'translateY(-4px)',
          boxShadow: theme.shadows[8],
        },
      }}
    >
      <CardContent sx={{ flexGrow: 1 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 2 }}>
          <Typography variant="h6" component="h2" sx={{ fontWeight: 600 }}>
            {meal.name}
          </Typography>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Chip
              label={`${meal.prepTime} min`}
              size="small"
              color="primary"
              variant="outlined"
            />
            <IconButton
              size="small"
              onClick={() => setIsEditing(!isEditing)}
              sx={{
                color: theme.palette.primary.main,
                '&:hover': {
                  bgcolor: theme.palette.primary.light + '20',
                },
              }}
            >
              <EditIcon />
            </IconButton>
          </Box>
        </Box>

        <Typography 
          variant="body2" 
          color="text.secondary" 
          sx={{ 
            mb: 2,
            display: '-webkit-box',
            WebkitLineClamp: 3,
            WebkitBoxOrient: 'vertical',
            overflow: 'hidden',
          }}
        >
          {meal.description}
        </Typography>

        <Box sx={{ mb: 2 }}>
          <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 1 }}>
            Ingrediënten:
          </Typography>
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
            {meal.ingredients.map((ingredient, index) => (
              <Chip
                key={index}
                label={`${ingredient.amount} ${ingredient.unit} ${ingredient.name}`}
                size="small"
                variant="outlined"
                sx={{ 
                  bgcolor: theme.palette.background.paper,
                  '&:hover': {
                    bgcolor: theme.palette.action.hover,
                  },
                }}
              />
            ))}
          </Box>
        </Box>

        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Typography variant="subtitle2" sx={{ fontWeight: 600 }}>
            Beoordeling:
          </Typography>
          <MuscleRating
            value={meal.rating}
            onChange={(_, newValue) => onUpdateRating(meal.id, newValue || 0)}
          />
        </Box>
      </CardContent>

      <CardActions sx={{ p: 2, pt: 0 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, width: '100%' }}>
          {isEditing ? (
            <TextField
              size="small"
              type="number"
              value={servings}
              onChange={handleServingsChange}
              onKeyPress={handleKeyPress}
              onBlur={() => setIsEditing(false)}
              InputProps={{
                sx: {
                  width: 100,
                  '& input': {
                    textAlign: 'center',
                  },
                },
              }}
            />
          ) : (
            <Typography variant="body2" color="text.secondary">
              {servings} {servings === 1 ? 'portie' : 'porties'}
            </Typography>
          )}
          <Box sx={{ flexGrow: 1 }} />
          <Chip
            label="Bekijk recept"
            color="primary"
            onClick={() => onSelect(meal)}
            sx={{
              fontWeight: 600,
              '&:hover': {
                bgcolor: theme.palette.primary.dark,
              },
            }}
          />
        </Box>
      </CardActions>
    </Card>
  );
};

export default MealCard; 