import React, { useState } from 'react';
import {
  Box,
  Typography,
  Grid,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  IconButton,
  useTheme,
  useMediaQuery,
  Chip,
  Card,
  CardContent,
  CardActions,
  CardMedia,
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import RemoveIcon from '@mui/icons-material/Remove';
import { Recipe, MealPlan } from '../types/Recipe';
import { predefinedMeals as meals } from '../data/meals';

interface MealPlannerProps {
  mealPlan: MealPlan;
  onAddMeal: (meal: Recipe, servings: number) => void;
  onUpdateServings: (mealId: string, servings: number) => void;
  onUpdateRating: (mealId: string, rating: number) => void;
  selectedMeal: Recipe | null;
  onSelectMeal: (meal: Recipe | null) => void;
  onShoppingListUpdate: (ingredients: { name: string; amount: number; unit: string }[]) => void;
  selectedCategory: string;
}

const MealPlanner: React.FC<MealPlannerProps> = ({
  mealPlan,
  onAddMeal,
  onUpdateServings,
  onUpdateRating,
  selectedMeal,
  onSelectMeal,
  onShoppingListUpdate,
  selectedCategory,
}) => {
  const [isAddDialogOpen, setIsAddDialogOpen] = useState(false);
  const [selectedMealToAdd, setSelectedMealToAdd] = useState<Recipe | null>(null);
  const [servings, setServings] = useState(1);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const getMealCategory = (mealId: string): string => {
    const id = parseInt(mealId);
    if (id >= 100 && id < 200) return 'breakfast';
    if (id >= 200 && id < 300) return 'lunch';
    if (id >= 300 && id < 400) return 'snack';
    return 'dinner';
  };

  const filteredMeals = selectedCategory === 'all'
    ? meals
    : meals.filter(meal => getMealCategory(meal.id) === selectedCategory);

  const categoryTitles: Record<string, string> = {
    all: 'Alle maaltijden',
    breakfast: 'Ontbijt',
    lunch: 'Lunch',
    dinner: 'Avondmaaltijd',
    snack: 'Snacks',
  };

  const handleAddMeal = (meal: Recipe) => {
    setSelectedMealToAdd(meal);
    setServings(meal.servings);
    setIsAddDialogOpen(true);
  };

  const handleConfirmAdd = () => {
    if (selectedMealToAdd) {
      onAddMeal(selectedMealToAdd, servings);
      setIsAddDialogOpen(false);
      setSelectedMealToAdd(null);
      setServings(1);
    }
  };

  const handleUpdateServings = (mealId: string, newServings: number) => {
    onUpdateServings(mealId, newServings);
    const updatedMeals = mealPlan.meals.map(meal =>
      meal.id === mealId ? { ...meal, servings: newServings } : meal
    );
    const updatedIngredients = updatedMeals.flatMap(meal =>
      meal.ingredients.map(ingredient => ({
        name: ingredient.name,
        amount: ingredient.amount * meal.servings,
        unit: ingredient.unit,
      }))
    );
    onShoppingListUpdate(updatedIngredients);
  };

  return (
    <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      <Box sx={{ 
        display: 'flex', 
        alignItems: 'center', 
        justifyContent: 'space-between',
        mb: 3,
      }}>
        <Typography variant="h5" component="h2" sx={{ fontWeight: 600 }}>
          {categoryTitles[selectedCategory]}
        </Typography>
      </Box>

      <Box sx={{ 
        flexGrow: 1, 
        overflow: 'auto',
        '&::-webkit-scrollbar': {
          width: '8px',
        },
        '&::-webkit-scrollbar-track': {
          background: '#f1f1f1',
          borderRadius: '4px',
        },
        '&::-webkit-scrollbar-thumb': {
          background: theme.palette.primary.main,
          borderRadius: '4px',
          '&:hover': {
            background: theme.palette.primary.dark,
          },
        },
      }}>
        <Grid container spacing={3}>
          {filteredMeals.map((meal) => (
            <Grid item xs={12} sm={6} md={4} key={meal.id}>
              <Card 
                sx={{ 
                  height: '100%',
                  display: 'flex',
                  flexDirection: 'column',
                  transition: 'transform 0.2s, box-shadow 0.2s',
                  '&:hover': {
                    transform: 'translateY(-4px)',
                    boxShadow: theme.shadows[8],
                  },
                }}
              >
                <CardMedia
                  component="img"
                  height="140"
                  image={`https://source.unsplash.com/random/400x300/?${meal.name.toLowerCase().replace(/\s+/g, ',')}`}
                  alt={meal.name}
                />
                <CardContent sx={{ flexGrow: 1 }}>
                  <Typography 
                    variant="h6" 
                    component="h3" 
                    gutterBottom
                    sx={{ fontWeight: 600 }}
                  >
                    {meal.name}
                  </Typography>
                  <Typography 
                    variant="body2" 
                    color="text.secondary" 
                    sx={{ 
                      mb: 2,
                      display: '-webkit-box',
                      WebkitLineClamp: 3,
                      WebkitBoxOrient: 'vertical',
                      overflow: 'hidden',
                    }}
                  >
                    {meal.description}
                  </Typography>
                  <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2 }}>
                    <Chip
                      label={`${meal.prepTime} min`}
                      size="small"
                      color="primary"
                      variant="outlined"
                    />
                    <Chip
                      label={`${meal.servings} porties`}
                      size="small"
                      color="secondary"
                      variant="outlined"
                    />
                  </Box>
                </CardContent>
                <CardActions sx={{ p: 2, pt: 0 }}>
                  <Box sx={{ 
                    display: 'flex', 
                    alignItems: 'center', 
                    gap: 2, 
                    width: '100%',
                    justifyContent: 'space-between',
                  }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <IconButton
                        size="small"
                        onClick={() => handleUpdateServings(meal.id, Math.max(0, (mealPlan.meals.find(m => m.id === meal.id)?.servings || 0) - 1))}
                        disabled={!mealPlan.meals.find(m => m.id === meal.id)?.servings}
                        sx={{
                          color: theme.palette.error.main,
                          '&:hover': {
                            bgcolor: theme.palette.error.light + '20',
                          },
                        }}
                      >
                        <RemoveIcon />
                      </IconButton>
                      <Typography variant="body2" sx={{ minWidth: 30, textAlign: 'center' }}>
                        {mealPlan.meals.find(m => m.id === meal.id)?.servings || 0}
                      </Typography>
                      <IconButton
                        size="small"
                        onClick={() => handleAddMeal(meal)}
                        sx={{
                          color: theme.palette.success.main,
                          '&:hover': {
                            bgcolor: theme.palette.success.light + '20',
                          },
                        }}
                      >
                        <AddIcon />
                      </IconButton>
                    </Box>
                    <Button
                      variant="outlined"
                      size="small"
                      onClick={() => onSelectMeal(meal)}
                      sx={{
                        borderRadius: 2,
                        textTransform: 'none',
                        fontWeight: 600,
                      }}
                    >
                      Details
                    </Button>
                  </Box>
                </CardActions>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Box>

      <Dialog
        open={isAddDialogOpen}
        onClose={() => setIsAddDialogOpen(false)}
        maxWidth="xs"
        fullWidth
      >
        <DialogTitle>
          <Typography variant="h6" sx={{ fontWeight: 600 }}>
            Aantal porties
          </Typography>
        </DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            label="Aantal porties"
            type="number"
            fullWidth
            value={servings}
            onChange={(e) => setServings(parseInt(e.target.value) || 1)}
            InputProps={{
              inputProps: { min: 1 }
            }}
          />
        </DialogContent>
        <DialogActions>
          <Button 
            onClick={() => setIsAddDialogOpen(false)}
            sx={{ color: theme.palette.text.secondary }}
          >
            Annuleren
          </Button>
          <Button 
            onClick={handleConfirmAdd}
            variant="contained"
            sx={{
              borderRadius: 2,
              textTransform: 'none',
              fontWeight: 600,
              px: 3,
              '&:hover': {
                bgcolor: theme.palette.primary.dark,
              },
            }}
          >
            Toevoegen
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default MealPlanner; 